input.sparql:
SELECT ?point ?cls ?ts WHERE {
  ?zone rdfs:label "Perimeter_mid_ZN_3" .
  ?point brick:isAType ?cls .
  ?point ref:hasTimeseriesId ?ts .
  ?point brick:hasProperty ?zone | ?zone brick:hasSubArea ?point .
}

SELECT ?cls (COUNT(*) AS ?n) WHERE {
  ?x a ?cls .
} GROUP BY ?cls ORDER BY ?n

SELECT ?sensor ?pred ?obj ?ts WHERE {
  ?sensor a brick:Occupancy_Sensor .
  ?sensor ?pred ?obj .
  FILTER(?pred = brick:hasProperty || ?pred = rdfs:label || ?pred = brick:hasSubcomponent || ?pred = ref:hasExternalReference)
} LIMIT 20

SELECT ?sensor ?loc ?locLbl WHERE {
  ?sensor a brick:Occupancy_Sensor .
  ?sensor brick:hasLocation ?loc .
  ?loc rdfs:label ?locLbl .
} LIMIT 30

SELECT ?zone ?member ?mtype WHERE {
  ?zone rdfs:label "Perimeter_mid_ZN_3" .
  ?zone ?p ?member .
  ?member rdfs:label ?mlbl .
  ?member a ?mtype .
} LIMIT 50

SELECT ?room ?roomLbl ?hasSensor WHERE {
  ?zone rdfs:label "Perimeter_mid_ZN_3" .
  ?zone ?p ?room .
  ?room rdfs:label ?roomLbl .
  OPTIONAL {
    ?sensor a brick:Occupancy_Sensor .
    ?sensor brick:hasLocation ?room .
    ?sensor ref:hasExternalReference ?ref .
    ?ref ref:hasTimeseriesId ?tsid .
  }
  BIND(IF(?tsid != "", ?tsid, "none") AS ?hasSensor)
}
